594		private async computePromptSlashCommands(token: CancellationToken): Promise<readonly IChatPromptSlashCommand[]> {
595			const promptFiles = await this.listPromptFiles(PromptsType.prompt, token);
596			const useAgentSkills = this.configurationService.getValue(PromptsConfig.USE_AGENT_SKILLS);
597			const skills = useAgentSkills ? await this.listPromptFiles(PromptsType.skill, token) : [];
598			const slashCommandFiles = [...promptFiles, ...skills];
599			const details = await Promise.all(slashCommandFiles.map(async promptPath => {
600				try {
601					const parsedPromptFile = await this.parseNew(promptPath.uri, token);
602					return this.asChatPromptSlashCommand(parsedPromptFile, promptPath);
603				} catch (e) {
604					this.logger.error(`[computePromptSlashCommands] Failed to parse prompt file for slash command: ${promptPath.uri}`, e instanceof Error ? e.message : String(e));
605					return undefined;
606				}
607			}));
608			const result = [];
609			const seen = new ResourceSet();
610			for (const detail of details) {
611				if (detail) {
612					result.push(detail);
613					seen.add(detail.promptPath.uri);
614				}
615			}
616			for (const model of this.modelService.getModels()) {
617				if (model.getLanguageId() === PROMPT_LANGUAGE_ID && model.uri.scheme === Schemas.untitled && !seen.has(model.uri)) {
618					const parsedPromptFile = this.getParsedPromptFile(model);
619					result.push(this.asChatPromptSlashCommand(parsedPromptFile, { uri: model.uri, storage: PromptsStorage.local, type: PromptsType.prompt }));
620				}
621			}
622			return result;
623		}
