616				// Use the search service if a FileSearchProvider is available
617				const disregardIgnoreFiles = this.configService.getValue<boolean>('explorer.excludeGitIgnore');
618				const getExcludePattern = (folder: URI) => getExcludes(this.configService.getValue<ISearchConfiguration>({ resource: folder })) || {};
