656		private async findAgentMDsUsingFileService(folder: URI, token: CancellationToken): Promise<IResolvedAgentFile[]> {
657			const result: IResolvedAgentFile[] = [];
658			const agentsMdFileName = 'agents.md';
659	
660			const traverse = async (uri: URI): Promise<void> => {
661				if (token.isCancellationRequested) {
662					return;
663				}
664	
665				try {
666					const stat = await this.fileService.resolve(uri);
667					if (stat.isFile && stat.name.toLowerCase() === agentsMdFileName) {
668						const realPath = stat.isSymbolicLink ? await this.fileService.realpath(stat.resource) : undefined;
669						result.push({ uri: stat.resource, realPath, type: AgentFileType.agentsMd });
670					} else if (stat.isDirectory && stat.children) {
671						// Recursively traverse subdirectories
672						for (const child of stat.children) {
673							await traverse(child.resource);
674						}
675					}
676				} catch (error) {
677					// Ignore errors for individual files/folders (e.g., permission denied)
678					this.logService.trace(`[PromptFilesLocator] Error traversing ${uri.toString()}: ${error}`);
679				}
680			};
681	
682			await traverse(folder);
683			return result;
684		}
