[metadata] {"filePath": "/workspace/repo/src/vs/workbench/contrib/chat/common/promptSyntax/computeAutomaticInstructions.ts", "oldString": "	/**
	 * Combines the `applyTo` and `paths` attributes into a single comma-separated", "newString": "	/**
	 * When {@link PromptsConfig.SEARCH_ROOT_REPO_CUSTOMIZATIONS} is enabled, discovers customization
	 * files (`CLAUDE.md`, `.claude/CLAUDE.md`, `.github/copilot-instructions.md`, and `AGENTS.md`)
	 * located in parent directories above the workspace root folder(s) and adds them as instructions.
	 * This supports monorepos where the workspace folder is nested inside a parent repository.
	 */
	private async _addRootRepositoryInstructions(variables: ChatRequestVariableSet, telemetryEvent: InstructionsCollectionEvent, token: CancellationToken): Promise<void> {
		if (!this._configurationService.getValue(PromptsConfig.SEARCH_ROOT_REPO_CUSTOMIZATIONS)) {
			return;
		}

		const customizationFiles: readonly { readonly relativePath: string; readonly isClaudeMd: boolean }[] = [
			{ relativePath: CLAUDE_MD_FILENAME, isClaudeMd: true },
			{ relativePath: `${CLAUDE_CONFIG_FOLDER}/${CLAUDE_MD_FILENAME}`, isClaudeMd: true },
			{ relativePath: `.github/${COPILOT_CUSTOM_INSTRUCTIONS_FILENAME}`, isClaudeMd: false },
			{ relativePath: AGENT_MD_FILENAME, isClaudeMd: false },
		];

		const seen = new ResourceSet();
		for (const folder of this._workspaceService.getWorkspace().folders) {
			// Start from the parent of the workspace root folder and walk up to the filesystem root.
			let current = dirname(folder.uri);
			let previous: URI | undefined;
			while (!previous || !isEqual(current, previous)) {
				if (token.isCancellationRequested) {
					return;
				}
				for (const { relativePath, isClaudeMd } of customizationFiles) {
					const fileUri = joinPath(current, relativePath);
					if (seen.has(fileUri)) {
						continue;
					}
					seen.add(fileUri);

					try {
						const stat = await this._fileService.stat(fileUri);
						if (!stat.isFile) {
							continue;
						}
					} catch (error) {
						// file does not exist at this location
						continue;
					}

					variables.add(toPromptFileVariableEntry(fileUri, PromptFileVariableKind.Instruction, undefined, true));
					telemetryEvent.agentInstructionsCount++;
					if (isClaudeMd) {
						telemetryEvent.claudeMdCount++;
					}
					this._logService.trace(`[InstructionsContextComputer] Root repository customization file added: ${fileUri.toString()}`);
				}
				previous = current;
				current = dirname(current);
			}
		}
